(()=>{'use strict';const button=document.getElementById('run-connected-system'),box=document.getElementById('connected-run-results');function show(text){const p=document.createElement('p');p.textContent=text;box.append(p);}try{const previous=JSON.parse(sessionStorage.getItem('zuxuru-connected-run'));if(Array.isArray(previous)){previous.forEach(show);sessionStorage.removeItem('zuxuru-connected-run');}}catch{}button.onclick=async()=>{if(!window.designerCloudReady?.()){show('Wait for Cloud saved before running your system.');return;}button.disabled=true;box.replaceChildren();try{const r=await fetch('/api/system/run',{method:'POST'}),data=await r.json();if(!r.ok)throw Error(data.error||'System run failed.');const lines=[data.status,...data.steps.map(s=>s.name+': '+s.status+(s.message?' · '+s.message:'')+(s.tasksAdded!==undefined?' · '+s.tasksAdded+' proposed tasks':'')),data.notice];lines.forEach(show);sessionStorage.setItem('zuxuru-connected-run',JSON.stringify(lines));location.hash='#overview';location.reload();}catch(e){show(e.message+' Reload saved records before retrying.');button.disabled=false;}};})();
